using Microsoft.AspNetCore.Mvc; using Exercicio12_Estoque.Models; namespace Exercicio12_Estoque.Controllers; public class EstoqueController:Controller{private static readonly List<Produto> Dados=new(){new(){Id=1,Nome="Produto 1",Categoria="Categoria 2",Estoque=1,EstoqueMinimo=5,Preco=20},new(){Id=2,Nome="Produto 2",Categoria="Categoria 3",Estoque=0,EstoqueMinimo=5,Preco=40},new(){Id=3,Nome="Produto 3",Categoria="Categoria 1",Estoque=3,EstoqueMinimo=5,Preco=60},new(){Id=4,Nome="Produto 4",Categoria="Categoria 2",Estoque=4,EstoqueMinimo=5,Preco=80},new(){Id=5,Nome="Produto 5",Categoria="Categoria 3",Estoque=5,EstoqueMinimo=5,Preco=100},new(){Id=6,Nome="Produto 6",Categoria="Categoria 1",Estoque=6,EstoqueMinimo=5,Preco=120},new(){Id=7,Nome="Produto 7",Categoria="Categoria 2",Estoque=7,EstoqueMinimo=5,Preco=140},new(){Id=8,Nome="Produto 8",Categoria="Categoria 3",Estoque=0,EstoqueMinimo=5,Preco=160},new(){Id=9,Nome="Produto 9",Categoria="Categoria 1",Estoque=0,EstoqueMinimo=5,Preco=180},new(){Id=10,Nome="Produto 10",Categoria="Categoria 2",Estoque=1,EstoqueMinimo=5,Preco=200},new(){Id=11,Nome="Produto 11",Categoria="Categoria 3",Estoque=2,EstoqueMinimo=5,Preco=220},new(){Id=12,Nome="Produto 12",Categoria="Categoria 1",Estoque=3,EstoqueMinimo=5,Preco=240},new(){Id=13,Nome="Produto 13",Categoria="Categoria 2",Estoque=4,EstoqueMinimo=5,Preco=260},new(){Id=14,Nome="Produto 14",Categoria="Categoria 3",Estoque=5,EstoqueMinimo=5,Preco=280},new(){Id=15,Nome="Produto 15",Categoria="Categoria 1",Estoque=6,EstoqueMinimo=5,Preco=300},}public IActionResult Index()=>View(Dados); public IActionResult Baixo()=>View("Index",Dados.Where(x=>x.Estoque>0&&x.Estoque<=x.EstoqueMinimo)); public IActionResult Esgotados()=>View("Index",Dados.Where(x=>x.Estoque==0)); public IActionResult Alertas()=>View("Index",Dados.Where(x=>x.Estoque<=x.EstoqueMinimo));}
